(()=>{const $=id=>document.getElementById(id),esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');let manifest,runs,current,previous=null,token=0;const cache=new Map();
 async function json(url){const r=await fetch(url);if(!r.ok)throw Error('Could not load '+url);return r.json();}
 async function report(id){if(!cache.has(id))cache.set(id,await json(runs.find(r=>r.id===id).report));return cache.get(id);}
 const metric=(label,value,note='')=>`<div class="metric">${label}<strong>${value}</strong><small>${note}</small></div>`;
 function render(){const index=new Map(current.rows.map(r=>[r.id,r])),items=manifest.images.filter(i=>($('split').value==='all'||i.split===$('split').value)&&(!$('group').value||i.expectedLabel===$('group').value)).map(i=>({...i,...index.get(i.id)})).filter(i=>!$('status').value||i.status===$('status').value),s=BenchmarkMetrics.summarize(items);$('summary').innerHTML=metric('Untied first candidate',s.top1+' / '+s.total,'Reference-label agreement')+metric('Strict top three',s.top3+' / '+s.total,'Whole tie group must fit')+metric('Tie-inclusive top three',s.top3TieInclusive+' / '+s.total)+metric('Tied / unresolved',s.counts.tied+' / '+s.counts.unresolved)+metric('Processing errors',s.counts.error)+metric('Leaf evidence available',s.leafAvailable,s.leafWins+' wins · '+s.leafLosses+' regressions');
 $('rowCount').textContent=`${items.length} photographs shown · ${s.total} processed · ${items.length-s.total} not run. Summary follows filters.`;
 $('rows').innerHTML=items.map(r=>{const ran=r.status!=='not_run',picture=(url,alt)=>url?`<a href="${esc(url)}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(url)}" alt="${alt}"></a>`:'—';return `<tr><td>${picture(r.image,'Reference photograph')}<small>${esc(r.id)} · ${esc(r.split)}</small><a href="${esc(r.sourcePage)}" target="_blank" rel="noopener">Commons source</a><small>${esc(r.author)}</small><a href="${esc(r.licenseUrl)}" target="_blank" rel="noopener">${esc(r.license)}</a></td><td>${picture(r.flowerMask,'Proposed flower mask')}<small>${ran?'Mask not manually graded':'Not evaluated'}</small></td><td>${picture(r.leafMask,'Nearby leaf candidate')}<small>${ran?(r.leafAvailable?'Shape evidence available · association unverified':'Leaf evidence unresolved'):'Not evaluated'}</small></td><td><strong>${esc(r.name)}</strong><small>${esc(r.referenceTaxon)}</small><small>${esc(r.stage)} · ${esc(r.view)}</small><small>${esc(r.labelStatus)}</small></td><td>${ran?`<ol>${(r.candidates||[]).slice(0,3).map(c=>`<li>${esc(c.name)} <strong>${c.score.toFixed(3)}</strong><small>Flower ${(c.flower_score??c.score).toFixed(3)} · leaf Δ ${(c.leaf_adjustment||0).toFixed(3)}</small></li>`).join('')}</ol><small>${esc(r.quality?.issues?.join('; ')||r.reason||'')}</small>`:'Reserved / not run'}${ran?`<small>Flower-only result: ${esc(r.flowerOnly?.status||'error')}</small><small>${r.milliseconds} ms</small>`:''}</td><td><span class="badge ${esc(r.status)}">${esc(r.status.replaceAll('_',' '))}</span>${r.status==='tied'?`<small>Tied leaders: ${esc(r.leaders.join(', '))}</small>`:''}</td></tr>`;}).join('');
 $('runInfo').textContent=`Saved ${current.createdAt} · ${current.split} · engine ${current.rows.find(r=>r.engineVersion)?.engineVersion||'unknown'} · ${current.reservedExposed?'Reserved set exposed in this run':'Reserved set unrun in this snapshot'}`;
 if(previous){const d=BenchmarkMetrics.compare(current,previous);$('comparison').textContent=d.compatible?`Compared on ${d.paired} paired images: ${d.improved} improved · ${d.regressed} regressed · ${d.unchanged} unchanged (untied first-candidate agreement).`:d.reason;}else $('comparison').textContent=runs.length===1?'First saved baseline. Future runs can be compared here.':'Choose an earlier compatible run to compare.';
 }
 async function selectRun(){const t=++token;try{const next=await report($('run').value),prior=$('compare').value?await report($('compare').value):null;if(t!==token)return;current=next;previous=prior;render();$('download').disabled=false;}catch(e){$('runInfo').textContent=e.message;}}
 for(const id of ['split','group','status'])$(id).addEventListener('change',()=>current&&render());for(const id of ['run','compare'])$(id).addEventListener('change',selectRun);
 $('download').addEventListener('click',()=>{if(!current)return;const u=URL.createObjectURL(new Blob([JSON.stringify(current,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='flower-benchmark-'+current.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);});
 Promise.all([json('/benchmark/manifest.json'),json('/benchmark/runs.json')]).then(([m,r])=>{manifest=m;runs=r;if(!r.length){$('runInfo').textContent='No saved runs yet';return;}const options=r.map(x=>`<option value="${esc(x.id)}">${esc(x.createdAt)} · ${esc(x.split)}</option>`).join('');$('run').innerHTML=options;$('compare').innerHTML='<option value="">No comparison</option>'+options;const groups=new Map(m.images.map(i=>[i.expectedLabel,i.name]));$('group').innerHTML='<option value="">All groups</option>'+[...groups].map(([id,name])=>`<option value="${id}">${esc(name)}</option>`).join('');selectRun();}).catch(e=>{$('runInfo').textContent=e.message;});
})();
